def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('destination',nargs='?',default='immersive-threejs-studio')
    parser.add_argument('--verify-only',action='store_true',help='Check embedded file integrity without writing')
    args=parser.parse_args()
    raw=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    files={}
    for name,encoded in raw.items():
        rel=pathlib.PurePosixPath(name)
        if rel.is_absolute() or '..' in rel.parts:
            parser.error('Unsafe embedded path')
        content=base64.b64decode(encoded,validate=True)
        if hashlib.sha256(content).hexdigest()!=CHECKSUMS[name]:
            parser.error('Payload checksum mismatch')
        files[name]=content
    if args.verify_only:
        print(f'Integrity verified: {len(files)} files. No files written.')
        return
    dest=pathlib.Path(args.destination).expanduser().resolve()
    if dest.exists():
        parser.error('The destination already exists. Choose a new directory; nothing was overwritten.')
    dest.mkdir(parents=True)
    for name,content in files.items():
        target=dest/name
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(content)
    print(f'Created {dest}: studio workflow + 36 public skills.')
    print('Open the folder in VS Code, start Claude Code or Codex, and follow README.md.')
    print('No packages, hooks or website deployment were executed.')

if __name__=='__main__':
    main()
